UPDATE `content_blocks` b
JOIN `pages` p ON p.id = b.page_id
SET b.content = CASE p.url_path
  WHEN '/svatebni-foto-video' THEN '<img class="svc-detail__img" src="/storage/media/2026/07/img_6a6bcdf935daf3.86762074.webp" alt="Svatební fotograf a kameraman při práci" loading="lazy"><h2>Svatební den vyprávíme přirozeně</h2><p>Svatební fotografie a video tvoříme jako jeden sehraný tým. Od ranních příprav po večerní zábavu sledujeme skutečné emoce, vztahy a drobné situace, které během dne rychle utečou. Nechceme z vaší svatby dělat natáčecí plac. Většinu času pracujeme nenápadně a do dění vstupujeme jen tehdy, když je potřeba poradit se světlem, místem nebo jednoduchým postavením. Výsledkem je souvislý příběh, ve kterém poznáte sebe i atmosféru svého dne.</p><h2>Fotograf a kameraman v jednom týmu</h2><p>Fotografie zastaví konkrétní okamžik, film k němu vrátí pohyb, hlasy a hudbu. Proto plánujeme záběry společně a vzájemně si nepřekážíme. Před svatbou projdeme harmonogram, důležité osoby, přesuny i vaše priority. Upozorníme na místa, kde se hodí rezerva, a domluvíme způsob komunikace s koordinátorkou nebo svědky. Působíme v Olomouci, na Moravě i po celé České republice.</p><h2>Jak spolupráce probíhá</h2><p>Po nezávazné poptávce ověříme termín a doporučíme rozsah podle délky programu. Následuje konzultace, na které si vyjasníme styl, časový plán a podobu výstupů. Ve svatební den přijedeme s předstihem a průběžně hlídáme světlo, zvuk i bezpečné zálohování záznamu. Portrétní část vedeme srozumitelně a bez složitých póz. Pokud počasí nepřeje, společně vybereme krátkou alternativu nebo vhodné místo v interiéru.</p><h2>Co dostanete</h2><ul><li>pečlivě vybrané a upravené fotografie v online galerii,</li><li>svatební film nebo kratší sestřih podle zvolené varianty,</li><li>konzistentní barvy a styl fotografie i videa,</li><li>jasně domluvený termín předání a archivaci hotových výstupů.</li></ul><p>Rozsah jednotlivých variant najdete v <a href="/cenik">ceníku svatebního focení a videa</a>. Skutečné svatby si můžete prohlédnout v našem <a href="/nase-prace">portfoliu</a> a zkušenosti párů na stránce <a href="/hodnoceni">Reference</a>.</p><h2>Časté otázky</h2><h3>Musíme umět pózovat?</h3><p>Nemusíte. Dáváme jednoduché pokyny a pracujeme s pohybem, takže se můžete soustředit jeden na druhého.</p><h3>Kdy je vhodné rezervovat termín?</h3><p>Oblíbené soboty se plní s předstihem. Jakmile znáte datum a místo, <a href="/kontakt">napište nám</a>; ověříme dostupnost a navrhneme další postup.</p>'
  WHEN '/rodinne-a-portretni-foceni' THEN '<img class="svc-detail__img" src="/storage/media/2026/07/img_6a6bce74a44cf3.99956170.webp" alt="Přirozené rodinné a portrétní focení" loading="lazy"><h2>Focení bez stresu a nucených póz</h2><p>Rodinné a portrétní focení vedeme tak, aby bylo příjemné i pro lidi, kteří se před fotoaparátem necítí jistě. Děti nemusí sedět jako v katalogu a dospělí nemusí znát žádné pózy. Začínáme krátkým rozhovorem nebo procházkou, dáváme jednoduché pokyny a necháváme prostor pro přirozený pohyb. Díky tomu vznikají fotografie, na kterých jsou vztahy, humor i drobná gesta, ne jen lidé postavení vedle sebe.</p><h2>Rodiny, těhotenské fotografie i osobní portréty</h2><p>Fotíme rodiny s malými i většími dětmi, těhotenské fotografie, křtiny, páry i samostatné portréty. Předem se zeptáme, k čemu budou snímky sloužit a jaký styl vám vyhovuje. Jinak připravíme klidnou rodinnou sérii do alba a jinak profesní portrét pro web nebo sociální sítě. Doporučíme oblečení, které spolu barevně funguje, ale nebude působit jako kostým.</p><h2>Místo a vhodný čas</h2><p>V Olomouci a okolí můžeme fotografovat v parku, historickém centru, u vás doma nebo na místě, ke kterému máte vztah. Pro malé děti často volíme kratší focení a čas, kdy bývají odpočaté. Venkovní termín plánujeme podle světla a předpovědi; při dešti se včas domluvíme na náhradě nebo interiéru. Za klienty přijíždíme také po Moravě a po dohodě po celé České republice.</p><h2>Co je součástí</h2><ul><li>konzultace stylu, místa a oblečení,</li><li>citlivé vedení během focení,</li><li>výběr a profesionální úprava fotografií,</li><li>online galerie pro stažení a sdílení,</li><li>jasný termín dodání.</li></ul><p>Ukázky různých typů focení najdete v našem <a href="/nase-prace">portfoliu fotografií</a>. Orientační varianty jsou v <a href="/cenik">ceníku</a> a ověřené zkušenosti klientů na stránce <a href="/hodnoceni">Reference</a>.</p><h2>Časté otázky</h2><h3>Co když děti nebudou spolupracovat?</h3><p>To je běžné. Přizpůsobíme tempo, střídáme jednoduché aktivity a fotografujeme i chvíle mezi plánovanými záběry.</p><h3>Jak rezervovat focení?</h3><p>Přes <a href="/kontakt">kontaktní formulář</a> nám pošlete přibližný termín, počet lidí a představu. Ozveme se s dostupností a konkrétním doporučením.</p>'
  WHEN '/reklamni-foto-video' THEN '<img class="svc-detail__img" src="/storage/media/2026/07/img_6a6bce757369d5.39373414.webp" alt="Profesionální reklamní fotografie a video" loading="lazy"><h2>Vizuální obsah, který odpovídá vaší značce</h2><p>Reklamní fotografie a video připravujeme pro firmy, živnostníky, produkty, kapely i organizátory akcí. Nezačínáme technikou, ale cílem: kde se bude obsah používat, koho má oslovit a jakou důvěru má značka budovat. Díky tomu nevznikne jen sada hezkých záběrů, ale materiál, který můžete skutečně nasadit na web, sociální sítě, Google profil, do kampaně nebo firemní prezentace.</p><h2>Promyšlená příprava šetří čas</h2><p>Před realizací si ujasníme formáty, počet výstupů, lokaci, účinkující a termín. Pokud je potřeba, pomůžeme připravit jednoduchý scénář a seznam záběrů. U produktů řešíme materiály, barvy a detaily; u lidí prostředí, oblečení a přirozené situace. U videa plánujeme také zvuk, délku a varianty pro různé kanály. Rozsah odsouhlasíme předem, aby byl natáčecí den efektivní a bez zbytečných překvapení.</p><h2>Foto a video pro různá použití</h2><p>Jeden projekt může obsahovat firemní portréty, fotografie provozovny, produktové detaily, reportáž z akce i krátká vertikální videa. Výstupy připravíme s ohledem na konkrétní platformu a bezpečné ořezy. Působíme v Olomouci, na Moravě a podle rozsahu zakázky po celé České republice. Na místě pracujeme ohleduplně k provozu a domlouváme se s odpovědnou osobou.</p><h2>Co můžete objednat</h2><ul><li>firemní portréty a fotografie týmu,</li><li>produktové a interiérové fotografie,</li><li>reklamní spoty, rozhovory a prezentační video,</li><li>reportáž z konference, koncertu nebo firemní akce,</li><li>krátké formáty pro sociální sítě.</li></ul><p>Vybrané realizace jsou v našem <a href="/nase-prace">portfoliu foto a video projektů</a>. Orientační doplňky najdete v <a href="/cenik">ceníku</a>; přesnou nabídku připravíme podle zadání.</p><h2>Časté otázky</h2><h3>Musíme mít hotový scénář?</h3><p>Nemusíte. Stačí popsat cíl, publikum a kanály. Navrhneme rozsah i jednoduchou strukturu, kterou společně schválíme.</p><h3>Jak získat nabídku?</h3><p>Pošlete přes <a href="/kontakt">nezávaznou poptávku</a> typ firmy, zamýšlené použití a termín. Doplníme otázky, doporučíme vhodné výstupy a připravíme cenu na míru.</p>'
  ELSE b.content
END
WHERE b.block_key = 'body'
  AND p.url_path IN (
    '/svatebni-foto-video',
    '/rodinne-a-portretni-foceni',
    '/reklamni-foto-video'
  );
